// Class definition
public class Person
{
    // Auto-implemented properties
    public string Name { get; set; }
    public int Age { get; set; }

    // Constructor - initializes new Person objects
    public Person(string name, int age)
    {
        Name = name;
        Age = age;
    }

    // Method - behavior of a Person
    public void Introduce()
    {
        Console.WriteLine($"Hi, I'm {Name} and I'm {Age} years old.");
    }
}

// Creating objects (instances) from the Person class
var person1 = new Person("Alice", 25);
var person2 = new Person("Bob", 30);

person1.Introduce(); // Output: Hi, I'm Alice and I'm 25 years old.
person2.Introduce(); // Output: Hi, I'm Bob and I'm 30 years old.

public class Product
{
    // Private backing field
    private decimal price;
    private int stock;

    // Auto-implemented property (compiler creates a hidden backing field)
    public string Name { get; set; }

    // Property with validation logic
    public decimal Price
    {
        get { return price; }
        set
        {
            // Validation in the setter
            price = value >= 0 ? value : throw new ArgumentOutOfRangeException(nameof(value));
        }
    }

    // Read-only property (set only in constructor)
    public string Id { get; }

    // Computed (expression-bodied) property
    public string DisplayName => $"{Name} (${Price:F2})";

    // Property with custom get/set logic
    public int Stock
    {
        get { return stock; }
        set
        {
            if (value < 0)
                throw new ArgumentOutOfRangeException(nameof(value));
            stock = value;
        }
    }

    public Product(string name, decimal price, int stock)
    {
        Name = name;
        Price = price;
        Stock = stock;
        Id = Guid.NewGuid().ToString();
    }
}

public class Order
{
    public int Id { get; }
    public string CustomerName { get; set; }
    public DateTime CreatedAt { get; }
    public List<string> Items { get; } = new();

    // Primary constructor (C# 12)
    public Order(int id, string customerName)
    {
        Id = id;
        CustomerName = customerName;
        CreatedAt = DateTime.UtcNow;
    }

    // Secondary constructor chains to primary
    public Order(int id) : this(id, "Anonymous")
    {
        // Reuses the primary constructor logic
    }
}

// Usage
var order1 = new Order(101, "Alice");
var order2 = new Order(102); // CustomerName defaults to "Anonymous"

public class BankAccount
{
    public string AccountNumber { get; }
    public decimal Balance { get; private set; }

    public BankAccount(string accountNumber, decimal initialBalance)
    {
        AccountNumber = accountNumber;
        Balance = initialBalance;
    }

    // Method with a return value
    public bool Deposit(decimal amount)
    {
        if (amount <= 0) return false;
        Balance += amount;
        return true;
    }

    // Method with out parameter
    public bool TryWithdraw(decimal amount, out decimal remaining)
    {
        if (amount > 0 && amount <= Balance)
        {
            Balance -= amount;
            remaining = Balance;
            return true;
        }
        remaining = Balance;
        return false;
    }

    // Expression-bodied method
    public override string ToString() => $"Account {AccountNumber}: ${Balance:F2}";
}

